class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        n = len(s)
        # Augment the string with '1' at both ends
        s = '1' + s + '1'

        # Initialize variables
        dp = [0] * n
        max_count = 0

        for i in range(1, n):
            if s[i] == '1':
                dp[i] = dp[i-1] + 1
            else:
                dp[i] = dp[i-1]

            # Update the maximum count
            max_count = max(max_count, dp[i])

        return max_count

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        # Initialize variables to keep track of the current count of active sections
        left = 0
        right = 0
        max_active = 0

        # Iterate through the string
        for i in range(len(s)):
            # If the character is '1', increment the right pointer and update the maximum active sections
            if s[i] == '1':
                right += 1
                max_active = max(max_active, right)
            else:
                # If the character is '0', check if the trade can be performed
                if left < right:
                    # Perform the trade by converting '1's surrounded by '0's to all '0's
                    left = right - 1
                    right = left + 1
                    max_active = max(max_active, right)
                else:
                    # If the trade cannot be performed, reset the left pointer to the right pointer
                    left = right

        return max_active
